{
  "aggregate": "master_question",
  "pipeline": {{
    (() => {
      const targetDomain = this.params.domain || "";
      const limitCount = Number(this.params.questionLimit) || 10;
      const onlyWrong = this.params.onlyWrong === true || this.params.onlyWrong === "true";
      const bookmarksOnly = this.params.bookmarksOnly === true || this.params.bookmarksOnly === "true";

      let matchConditions = {};

      // 1. Einzelner Domain-Filter (String)
      if (typeof targetDomain === "string" && targetDomain.trim() !== "") {
        matchConditions["domain"] = targetDomain;
      }

      // 2. Zusätzlicher Filter für countWrong > 0, falls true
      if (onlyWrong) {
        matchConditions["countWrong"] = { "$exists": true, "$gt": 0 };
      }

      let pipeline = [];

      // Basis-Match (Domain & countWrong)
      pipeline.push({
        "$match": matchConditions
      });

      // 3. Lookup mit `bookmark` (1-zu-1 mit Typkonvertierung ObjectId -> String)
      pipeline.push({
        "$lookup": {
          "from": "bookmark",
          "let": { "idString": { "$toString": "$_id" } },
          "pipeline": [
            {
              "$match": {
                "$expr": { "$eq": ["$questionId", "$$idString"] }
              }
            }
          ],
          "as": "bookmarkMatch"
        }
      });

      // 4. Feld `hasBookmark` ("true" oder "no") hinzufügen
      pipeline.push({
        "$addFields": {
          "hasBookmark": {
            "$cond": {
              "if": { "$gt": [{ "$size": "$bookmarkMatch" }, 0] },
              "then": "true",
              "else": "no"
            }
          }
        }
      });

      // Temporäres Hilfsfeld entfernen
      pipeline.push({
        "$project": {
          "bookmarkMatch": 0
        }
      });

      // 5. Wenn 'bookmarksOnly' aktiv ist, direkt danach filtern
      if (bookmarksOnly) {
        pipeline.push({
          "$match": {
            "hasBookmark": "true"
          }
        });
      }

      // 6. Zufällige Auswahl ($sample) aus den gefilterten Dokumenten
      pipeline.push({ 
        "$sample": { "size": limitCount } 
      });

      // 7. Antworten per $lookup anhängen (master_answer)
      pipeline.push({
        "$lookup": {
          "from": "master_answer",
          "localField": "_id",
          "foreignField": "question_id",
          "as": "answers"
        }
      });

      return pipeline;
    })()
  }},
  "cursor": {
    "batchSize": {{ Number(this.params.questionLimit) || 10 }}
  }
}
